import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    y_at_x = [0] * n
    for i in range(n):
        x, y = data[1 + 2 * i:3 + 2 * i]
        y_at_x[x - 1] = y

    # comparable[i] contains every ball removed when ball i is chosen.
    comparable = [0] * n
    for i in range(n):
        mask = 0
        for j in range(n):
            if (i < j and y_at_x[i] < y_at_x[j]) or (
                i > j and y_at_x[i] > y_at_x[j]
            ):
                mask |= 1 << j
        comparable[i] = mask

    initial = (1 << n) - 1
    seen = {initial}
    stack = [initial]
    while stack:
        state = stack.pop()
        bits = state
        while bits:
            bit = bits & -bits
            bits -= bit
            i = bit.bit_length() - 1
            nxt = state & ~comparable[i]
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)

    print(len(seen) % 998244353)

solve()

