import sys
from collections import defaultdict

def factor(n):
    d=2
    out={}
    while d*d<=n:
        while n%d==0:
            out[d]=out.get(d,0)+1
            n//=d
        d+=1
    if n>1:
        out[n]=out.get(n,0)+1
    return out

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    N=data[0]
    fs=[factor(x) for x in data[1:]]
    ans=1
    for p in set().union(*(f.keys() for f in fs)):
        dp={(0,0):1}
        for f in fs:
            e=f.get(p,0)
            nd=defaultdict(int)
            if e:
                for (x,mn),v in dp.items():
                    for y in (x-e,x+e):
                        key=(y,min(mn,y))
                        nd[key]=(nd[key]+v*pow(p,y,MOD))%MOD
            else:
                # The valuation at the next position is unchanged.
                mult=pow(p, next(iter(dp))[0], MOD) if dp else 1
                for key,v in dp.items():
                    nd[key]=(nd[key]+v*mult)%MOD
            dp=nd
        val=0
        for (x,mn),v in dp.items():
            val=(val+v*pow(p,-N*mn,MOD))%MOD
        ans=ans*val%MOD
    print(ans)

solve()

