import sys

MOD = 998244353
MAX_A = 100000


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]

    # Smallest prime factor table.
    spf = list(range(MAX_A + 1))
    for p in range(2, 317):
        if spf[p] == p:
            for x in range(p * p, MAX_A + 1, p):
                if spf[x] == x:
                    spf[x] = p

    # Euler's totient function.
    phi = list(range(MAX_A + 1))
    for p in range(2, MAX_A + 1):
        if phi[p] == p:
            for x in range(p, MAX_A + 1, p):
                phi[x] -= phi[x] // p

    # weighted[d] = sum of 2^(i-1) over prior positions i with d | A_i
    weighted = [0] * (MAX_A + 1)
    divisor_cache = {}
    power = 1
    answer = 0
    output = []

    for value in values:
        divisors = divisor_cache.get(value)
        if divisors is None:
            factors = []
            x = value
            while x > 1:
                p = spf[x]
                exponent = 0
                while x % p == 0:
                    x //= p
                    exponent += 1
                factors.append((p, exponent))

            divisors = [1]
            for p, exponent in factors:
                old = divisors[:]
                multiplier = 1
                for _ in range(exponent):
                    multiplier *= p
                    divisors.extend(d * multiplier for d in old)
            divisor_cache[value] = divisors

        # gcd(u,v) = sum_{d|u, d|v} phi(d). Count contributions
        # ending at this position, then add this position to each divisor total.
        contribution = 0
        for d in divisors:
            contribution += phi[d] * weighted[d]
            updated = weighted[d] + power
            if updated >= MOD:
                updated -= MOD
            weighted[d] = updated

        answer = (2 * answer + contribution) % MOD
        output.append(str(answer))
        power = (2 * power) % MOD

    sys.stdout.write("\n".join(output))


if __name__ == "__main__":
    main()

