from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        # Active pairs, ordered by decreasing left endpoint.
        heap = []
        gains = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for a, pair_id in by_right[r]:
                heapq.heappush(heap, (-a, pair_id))

            if heap:
                neg_a, pair_id = heapq.heappop(heap)
                largest_left = -neg_a
                second_largest = -heap[0][0] if heap else 0
                # Removing the uniquely strongest active restriction improves
                # the count for this right endpoint by this difference.
                gains[pair_id] += largest_left - second_largest
                heapq.heappush(heap, (neg_a, pair_id))
            else:
                largest_left = 0

            base += r - largest_left

        return base + max(gains)

