import sys

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    try:
        n = next(it)
    except StopIteration:
        return
    m = next(it)
    q = next(it)

    edges = [None] * m
    for k in range(m):
        a = next(it) - 1
        b = next(it) - 1
        c = next(it)
        edges[k] = (a, b, c)

    queries = []
    deleted = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            idx = next(it) - 1
            queries.append((1, idx))
            deleted[idx] = True
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for k, (a, b, c) in enumerate(edges):
        if not deleted[k]:
            dist[a][b] = dist[b][a] = c

    # APSP in the graph remaining after all deletions.
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            di = dist[i]
            for j in range(n):
                candidate = dik + dk[j]
                if candidate < di[j]:
                    di[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            answers.append(-1 if dist[x][y] == inf else dist[x][y])
        else:
            _, idx = query
            a, b, c = edges[idx]
            # Save endpoint distances before adding the road. Any new shortest
            # path uses the newly added road at most once.
            da = [dist[i][a] for i in range(n)]
            db = [dist[i][b] for i in range(n)]
            for i in range(n):
                di = dist[i]
                ai = da[i] + c
                bi = db[i] + c
                for j in range(i, n):
                    candidate = min(ai + db[j], bi + da[j])
                    if candidate < di[j]:
                        di[j] = candidate
                        dist[j][i] = candidate

    print('\n'.join(map(str, reversed(answers))))

if __name__ == '__main__':
    main()

