    n, x = data[0], data[1]
    upper = data[2::2]
    lower = data[3::2]

    def feasible(h):
        lo = max(0, h - lower[0])
        hi = min(upper[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            allowed_lo = max(0, h - lower[i])
            allowed_hi = min(upper[i], h)
            lo = max(allowed_lo, lo - x)
            hi = min(allowed_hi, hi + x)
            if lo > hi:
                return False
        return True

    left = 0
    right = min(u + d for u, d in zip(upper, lower))
    while left < right:
        mid = (left + right + 1) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid - 1

    print(sum(upper) + sum(lower) - n * left)

