import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    rows = adj[:]
    pivots = []
    rank = 0
    for col in range(n):
        sel = next((r for r in range(rank, n) if (rows[r] >> col) & 1), None)
        if sel is None:
            continue
        rows[rank], rows[sel] = rows[sel], rows[rank]
        for r in range(n):
            if r != rank and ((rows[r] >> col) & 1):
                rows[r] ^= rows[rank]
        pivots.append((col, rank))
        rank += 1

    pivot_cols = {c for c, _ in pivots}
    free = [c for c in range(n) if c not in pivot_cols]
    if not free:
        print('No')
        return

    # Use a basis of the nullspace as the bit columns of the vertex labels.
    ans = [0] * n
    for j, f in enumerate(free):
        vec = 1 << f
        for c, r in pivots:
            if (rows[r] >> f) & 1:
                vec |= 1 << c
        for v in range(n):
            if (vec >> v) & 1:
                ans[v] |= 1 << j

    if any(x == 0 for x in ans):
        print('No')
        return

    # Keeping two low bits unused is harmless when the labels still fit.
    if n > 1 and len(free) <= 58:
        ans = [x << 2 for x in ans]
    print('Yes')
    print(*ans)

