class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        # Directions in clockwise order: SE, SW, NW, NE.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # straight[d][p][i]: longest straight valid continuation beginning
        # at i, expecting 0 when p=0 and 2 when p=1.
        straight = [[[0] * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    rr, cc = r + dr, c + dc
                    nxt = rr * m + cc if 0 <= rr < n and 0 <= cc < m else -1
                    for p, value in enumerate((0, 2)):
                        if grid[r][c] == value:
                            straight[d][p][i] = 1 + (straight[d][1 - p][nxt] if nxt >= 0 else 0)

        # turned[d][p][i] allows a clockwise turn once, or no turn.
        turned = [[[0] * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            td = (d + 1) % 4
            tr, tc = dirs[td]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    rr, cc = r + dr, c + dc
                    nxt = rr * m + cc if 0 <= rr < n and 0 <= cc < m else -1
                    rr, cc = r + tr, c + tc
                    turn_next = rr * m + cc if 0 <= rr < n and 0 <= cc < m else -1
                    for p, value in enumerate((0, 2)):
                        if grid[r][c] == value:
                            continue_same = turned[d][1 - p][nxt] if nxt >= 0 else 0
                            after_turn = straight[td][1 - p][turn_next] if turn_next >= 0 else 0
                            turned[d][p][i] = 1 + max(continue_same, after_turn)

