from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        unused = set(range(1, n + 1))
        answer = []
        last_parity = None

        def completions(next_parity: int) -> int:
            remaining = len(unused)
            if remaining == 0:
                return 1

            even = sum(1 for value in unused if value % 2 == 0)
            odd = remaining - even
            required_first = (remaining + 1) // 2
            required_second = remaining // 2

            if next_parity == 0:
                if even != required_first or odd != required_second:
                    return 0
            else:
                if odd != required_first or even != required_second:
                    return 0

            return fact[even] * fact[odd]

        for _ in range(n):
            chosen = None
            for value in sorted(unused):
                parity = value % 2
                if last_parity is not None and parity == last_parity:
                    continue

                unused.remove(value)
                count = completions(1 - parity) if unused else 1
                if k > count:
                    k -= count
                    unused.add(value)
                else:
                    chosen = value
                    answer.append(value)
                    last_parity = parity
                    break

            if chosen is None:
                return []

        return answer

