class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1 % k] * n
        for j in range(1, n):
            powers[j] = powers[j - 1] * 10 % k

        # The coefficient of each chosen digit in the full palindrome's
        # value, modulo k.
        coeff = []
        for i in range(m):
            if n % 2 == 1 and i == m - 1:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[n - 1 - i]) % k)

        # dp[i] is a bitmask of remainders achievable by positions i..m-1.
        dp = [0] * (m + 1)
        dp[m] = 1  # remainder zero
        for i in range(m - 1, -1, -1):
            mask = 0
            nxt = dp[i + 1]
            c = coeff[i]
            for r in range(k):
                if (nxt >> r) & 1:
                    for digit in range(10):
                        mask |= 1 << ((r + digit * c) % k)
            dp[i] = mask

        # Greedily fix each digit from left to right, retaining feasibility.
        target = 0
        half = []
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                remaining = (target - digit * c) % k
                if (dp[i + 1] >> remaining) & 1:
                    half.append(str(digit))
                    target = remaining
                    break

        h = ''.join(half)
        return h + (h[:-1][::-1] if n % 2 else h[::-1])

