from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nxt[i] = stack[-1]
            stack.append(i)

        levels = n.bit_length()
        jumps = [nxt]
        sums = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        for _ in range(1, levels):
            prev_jump = jumps[-1]
            prev_sum = sums[-1]
            curr_jump = [n] * n
            curr_sum = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    curr_jump[i] = prev_jump[mid]
                    curr_sum[i] = prev_sum[i] + prev_sum[mid]
                else:
                    curr_sum[i] = prev_sum[i]
            jumps.append(curr_jump)
            sums.append(curr_sum)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def cost(left, right):
            total = 0
            pos = left
            for b in range(levels - 1, -1, -1):
                dest = jumps[b][pos]
                if dest <= right:
                    total += sums[b][pos]
                    pos = dest
            total += nums[pos] * (right - pos + 1)
            return total - (prefix[right + 1] - prefix[left])

        answer = 0
        for right in range(n):
            low, high = 0, right + 1
            while low < high:
                mid = (low + high) // 2
                if cost(mid, right) <= k:
                    high = mid
                else:
                    low = mid + 1
            answer += right - low + 1
        return answer

