class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n=len(edges)+1
        g=[[] for _ in range(n)]
        for u,v,w in edges:
            g[u].append((v,w)); g[v].append((u,w))
        parent=[-1]*n
        pw=[0]*n
        order=[0]
        parent[0]=0
        for u in order:
            for v,w in g[u]:
                if v != parent[u]:
                    parent[v]=u; pw[v]=w; order.append(v)
        d0=[0]*n; d1=[0]*n
        for u in reversed(order):
            base=0; gains=[]
            for v,w in g[u]:
                if parent[v]==u:
                    base += d0[v]
                    gains.append(w+d1[v]-d0[v])
            gains.sort(reverse=True)
            pos=[x for x in gains if x>0]
            d0[u]=base+sum(pos[:k])
            d1[u]=base+sum(pos[:max(0,k-1)])
        return d0[0]

