from functools import lru_cache
import sys

sys.setrecursionlimit(1_000_000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M, L = data[:3]
    vals = data[3:]
    total = N + M + L
    allmask = (1 << total) - 1

    @lru_cache(None)
    def win(takahashi, aoki, turn):
        hand = takahashi if turn == 0 else aoki
        other = aoki if turn == 0 else takahashi
        if hand == 0:
            return False

        bits = hand
        while bits:
            card = bits & -bits
            bits -= card
            i = card.bit_length() - 1
            new_hand = hand ^ card
            table = allmask ^ (new_hand | other)

            # Playing the card without taking anything is always permitted.
            if turn == 0:
                if not win(new_hand, other, 1):
                    return True
            else:
                if not win(other, new_hand, 0):
                    return True

            eligible = table
            while eligible:
                taken = eligible & -eligible
                eligible -= taken
                j = taken.bit_length() - 1
                if vals[j] < vals[i]:
                    if turn == 0:
                        if not win(new_hand | taken, other, 1):
                            return True
                    else:
                        if not win(other, new_hand | taken, 0):
                            return True
        return False

    initial_t = (1 << N) - 1
    initial_a = ((1 << M) - 1) << N
    print("Takahashi" if win(initial_t, initial_a, 0) else "Aoki")

if __name__ == "__main__":
    main()

