from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first, middle, last = p.split('*')
        n = len(s)

        def occurrences(pattern):
            if not pattern:
                return list(range(n + 1))

            m = len(pattern)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    found.append(i - m + 1)
                    j = prefix[j - 1]
            return found

        first_positions = occurrences(first)
        middle_positions = occurrences(middle)
        last_positions = occurrences(last)

        best = n + 1
        for mid_start in middle_positions:
            # Latest first-segment occurrence that ends before this middle one.
            i = bisect_right(first_positions, mid_start - len(first)) - 1
            # Earliest last-segment occurrence that begins after the middle one.
            j = bisect_left(last_positions, mid_start + len(middle))
            if i >= 0 and j < len(last_positions):
                length = last_positions[j] + len(last) - first_positions[i]
                best = min(best, length)

        return -1 if best == n + 1 else best

