from typing import List

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        dp_a = [0] * n
        dp_b = [0] * n
        dp_a[0] = energyDrinkA[0]
        dp_b[0] = energyDrinkB[0]

        for i in range(1, n):
            # Continue the same drink, or switch after a one-hour cleanse.
            # Starting at this hour is also allowed.
            dp_a[i] = energyDrinkA[i] + max(
                dp_a[i - 1], dp_b[i - 2] if i >= 2 else 0, 0
            )
            dp_b[i] = energyDrinkB[i] + max(
                dp_b[i - 1], dp_a[i - 2] if i >= 2 else 0, 0
            )

        return max(dp_a[-1], dp_b[-1])

