import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        prime = [True] * limit
        prime[0] = prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        width = len(str(n))
        places = [10 ** i for i in range(width)]
        inf = 10 ** 30
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for place in places:
                digit = (x // place) % 10
                if digit < 9:
                    nxt = x + place
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))
                if digit > 0 and not (place == 10 ** (width - 1) and digit == 1):
                    nxt = x - place
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))

        return -1

