from array import array

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z0[i] is the common-prefix length of nums and nums[i:].
        z0 = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z0[i] = min(right - i, z0[i - left])
            while i + z0[i] < n and nums[z0[i]] == nums[i + z0[i]]:
                z0[i] += 1
            if i + z0[i] > right:
                left, right = i, i + z0[i]

        answer = 0
        # lcp[i][j] is computed from lcp[i+1][j+1]. Only the next
        # row is needed, so the memory use is O(n).
        next_row = array('H', [0]) * (n + 1)
        for i in range(n - 2, 0, -1):
            # First-prefix condition holds for every d=j-i >= i.
            first = z0[i] >= i
            if first:
                answer += max(0, n - max(i + 1, 2 * i))

            row = array('H', [0]) * (n + 1)
            # For nums[i:j] to prefix nums[j:], require 2*(j-i) <= n-i.
            last_j = (n + i) // 2
            for j in range(i + 1, last_j + 1):
                if nums[i] == nums[j]:
                    row[j] = next_row[j + 1] + 1
                    if row[j] >= j - i and not (first and j - i >= i):
                        answer += 1
            next_row = row
        return answer

