class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        active = s.count('1')

        # Run-length encode the augmented string.
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        zero_runs = [(idx, length) for idx, (ch, length) in enumerate(runs) if ch == '0']
        largest_zeros = sorted(zero_runs, key=lambda item: item[1], reverse=True)[:3]

        best_gain = 0
        for k, (ch, one_length) in enumerate(runs):
            if ch != '1' or k == 0 or k == len(runs) - 1:
                continue
            if runs[k - 1][0] != '0' or runs[k + 1][0] != '0':
                continue

            # The removed one-run joins its neighboring zero-runs into one.
            best_gain = max(best_gain, runs[k - 1][1] + runs[k + 1][1])

            # Alternatively, convert a different zero-run after the removal.
            for zero_idx, zero_length in largest_zeros:
                if zero_idx != k - 1 and zero_idx != k + 1:
                    best_gain = max(best_gain, zero_length - one_length)
                    break

        return active + best_gain

