class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}
        n = len(word)
        total = 0

        for left in range(n):
            seen = set()
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    seen.add(ch)
                else:
                    consonants += 1

                # Consonant count can only increase as the substring grows.
                if consonants > k:
                    break
                if consonants == k and len(seen) == 5:
                    total += 1

        return total

