class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        # Every valid copy differs from original by the same integer shift.
        min_shift = max(bounds[i][0] - original[i] for i in range(len(original)))
        max_shift = min(bounds[i][1] - original[i] for i in range(len(original)))
        return max(0, max_shift - min_shift + 1)

